"""Request-path helpers shared by authentication and dispatch.

Versioned routes and proxy spellings should pass through one helper so a
documented path and a harmless alternate spelling reach the same decision.
"""
from __future__ import annotations

from urllib.parse import unquote


def canonical_path(raw_path: str) -> str:
    """Compatibility spelling: decode, collapse slashes, drop one trailing slash."""

    path = unquote(raw_path)
    while "//" in path:
        path = path.replace("//", "/")
    if len(path) > 1:
        path = path.rstrip("/")
    return path or "/"


def auth_path(raw_path: str) -> str:
    """Path used to look up the route table before reading a body."""

    # Look up the route using the same path spelling the rest of the service uses.
    return canonical_path(raw_path)


def dispatch_path(raw_path: str) -> str:
    """Path handed to the handler after the route decision."""

    # Hand the handler the same path the route lookup used.
    return auth_path(raw_path)

"""Storage-independent contract for the audit-log service.

Nothing here assumes a particular backend (file, database, memory): a
concrete store implements this contract, and every other caller depends
only on it. The trail it exposes is append-only, and replica bookkeeping
(names, replay cursors, promotion labels) is kept separate from event
identity, as required by ``auditlog.models``.
"""

from __future__ import annotations

import abc
from typing import Any, Iterator, Optional

from auditlog.models import AuditEvent, ReplayCursor, Replica


class AuditLogService(abc.ABC):
    """Append-only event trail plus replica/replay-cursor bookkeeping."""

    @abc.abstractmethod
    def record(
        self,
        actor: str,
        action: str,
        outcome: str,
        recorded_at: str,
        metadata: Optional[dict[str, Any]] = None,
    ) -> AuditEvent:
        """Append a new event and return it.

        Entries are never edited, removed, or reordered; a correction is a
        further recorded entry, not a change to an existing one.
        """

    @abc.abstractmethod
    def events(self, since_sequence: int = 0) -> Iterator[AuditEvent]:
        """Replay recorded events in sequence order, after ``since_sequence``."""

    @abc.abstractmethod
    def register_replica(self, name: str) -> Replica:
        """Create a new named replay target."""

    @abc.abstractmethod
    def get_cursor(self, replica_id: str) -> Optional[ReplayCursor]:
        """Return a replica's current replay position, or ``None`` if it has not replayed anything."""

    @abc.abstractmethod
    def advance_cursor(
        self,
        replica_id: str,
        offset: int,
        last_event_id: Optional[str] = None,
    ) -> ReplayCursor:
        """Record how far a replica has replayed. Never affects event identity."""

    @abc.abstractmethod
    def promote_replica(self, replica_id: str, promotion_label: str) -> Replica:
        """Attach a promotion label to a replica.

        Promotion is bookkeeping about the replica, never a rewrite of any
        already-accepted event's identity.
        """

"""Stable complete-identity helpers for compatibility repair."""

from __future__ import annotations


def complete_event_identity(recorded_at: str, content_id: str) -> str:
    """Return complete immutable event identity."""

    return "\x1f".join((recorded_at, content_id))


def durable_repair_key(actor: str, action: str, outcome: str, recorded_at: str, content_id: str) -> str:
    """Persist complete event identity for later repair."""

    return complete_event_identity(recorded_at, content_id)


def repair_group_key(stored_repair_key: str | None, recorded_at: str, content_id: str) -> str:
    """Recompute complete identity before compatibility grouping."""

    complete = complete_event_identity(recorded_at, content_id)
    if stored_repair_key == complete:
        return stored_repair_key
    return complete

