cd /private/var/folders/sp/k4h4yd5j4bj0zwbwzps0yj8c0000gp/T/lcm-live-xxyb_t_3/audit-route-s03/maintenance/inputs/s03-promotion-procedures/ && python3 <<'PY'
import json, re, csv

def parse_md(path):
    out = {}
    with open(path) as f:
        for line in f:
            m = re.match(r"- \*\*(audit-route-s03-t05-\d{6})\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*)$", line.strip())
            if m:
                case, system, status, note = m.groups()
                out[case] = (system, status, note)
    return out

def parse_jsonl(path):
    out = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            rec = json.loads(line)
            out[rec["case"]] = (rec["system"], rec["status"], rec["note"])
    return out

def parse_csv(path):
    out = {}
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            out[row["case"]] = (row["system"], row["status"], row["note"])
    return out

def parse_yaml(path):
    out = {}
    case = system = status = note = None
    with open(path) as f:
        for line in f:
            line = line.rstrip("\n")
            if line.startswith("- case:"):
                if case:
                    out[case] = (system, status, note)
                case = line.split(":", 1)[1].strip()
                system = status = note = None
            elif line.strip().startswith("system:"):
                system = line.split(":", 1)[1].strip()
            elif line.strip().startswith("status:"):
                status = line.split(":", 1)[1].strip()
            elif line.strip().startswith("note:"):
                note = line.split(":", 1)[1].strip().strip('"')
        if case:
            out[case] = (system, status, note)
    return out

def parse_log(path):
    out = {}
    pat = re.compile(r'case=(\S+) system=(\S+) status=(\S+) note="(.*)"$')
    with open(path) as f:
        for line in f:
            m = pat.match(line.strip())
            if m:
                case, system, status, note = m.groups()
                out[case] = (system, status, note)
    return out

files = {
    "md": ("audit-route-s03-t05-evidence-01.md", parse_md),
    "jsonl": ("audit-route-s03-t05-evidence-02.jsonl", parse_jsonl),
    "csv": ("audit-route-s03-t05-evidence-03.csv", parse_csv),
    "yaml": ("audit-route-s03-t05-evidence-04.yaml", parse_yaml),
    "log": ("audit-route-s03-t05-evidence-05.log", parse_log),
}

parsed = {}
for key, (path, fn) in files.items():
    data = fn(path)
    parsed[key] = data
    nums = sorted(int(c.split("-")[-1]) for c in data)
    print(f"{key}: {path} -> {len(data)} records, case range {nums[0]}-{nums[-1]}, contiguous={nums == list(range(nums[0], nums[-1]+1))}")

min_max = min(max(int(c.split('-')[-1]) for c in d) for d in parsed.values())
print(f"\nOverlap upper bound across all 5 files: case {min_max}")

mismatches = []
for n in range(1, min_max + 1):
    case = f"audit-route-s03-t05-{n:06d}"
    values = {k: parsed[k].get(case) for k in parsed}
    if len(set(values.values())) != 1:
        mismatches.append((case, values))

print(f"Mismatches within overlapping range (1-{min_max}): {len(mismatches)}")
for m in mismatches[:10]:
    print(m)

rotation = {1: ("macos-arm64", "recorded"), 2: ("linux-x86_64", "follow-up"), 3: ("windows-x86_64", "supported"), 0: ("freebsd-x86_64", "review")}
for key, data in parsed.items():
    violations = 0
    for case, (system, status, note) in data.items():
        n = int(case.split("-")[-1])
        expected = rotation[n % 4]
        if (system, status) != expected:
            violations += 1
    print(f"{key}: rotation violations = {violations} (of {len(data)})")
PY

