python3 << 'EOF'
import json, csv, re

def parse_md(path):
    d = {}
    with open(path) as f:
        for line in f:
            m = re.match(r'- \*\*(\S+)\*\* \| System: (\S+) \| Status: (\S+) \| Evidence: (.*)$', line.strip())
            if m:
                case, system, status, note = m.groups()
                d[case] = (system, status, note)
    return d

def parse_jsonl(path):
    d = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            o = json.loads(line)
            d[o['case']] = (o['system'], o['status'], o['note'])
    return d

def parse_csv(path):
    d = {}
    with open(path) as f:
        r = csv.DictReader(f)
        for row in r:
            d[row['case']] = (row['system'], row['status'], row['note'])
    return d

def parse_yaml(path):
    d = {}
    case = system = status = note = None
    with open(path) as f:
        for line in f:
            line = line.rstrip('\n')
            if line.startswith('- case:'):
                if case:
                    d[case] = (system, status, note)
                case = line.split('- case:')[1].strip()
                system = status = note = None
            elif line.strip().startswith('system:'):
                system = line.split('system:')[1].strip()
            elif line.strip().startswith('status:'):
                status = line.split('status:')[1].strip()
            elif line.strip().startswith('note:'):
                note = line.split('note:', 1)[1].strip().strip('"')
        if case:
            d[case] = (system, status, note)
    return d

def parse_log(path):
    d = {}
    with open(path) as f:
        for line in f:
            m = re.match(r'case=(\S+) system=(\S+) status=(\S+) note="(.*)"$', line.strip())
            if m:
                case, system, status, note = m.groups()
                d[case] = (system, status, note)
    return d

files = {
    'evidence-01.md': parse_md('audit-route-s03-t08-evidence-01.md'),
    'evidence-02.jsonl': parse_jsonl('audit-route-s03-t08-evidence-02.jsonl'),
    'evidence-03.csv': parse_csv('audit-route-s03-t08-evidence-03.csv'),
    'evidence-04.yaml': parse_yaml('audit-route-s03-t08-evidence-04.yaml'),
    'evidence-05.log': parse_log('audit-route-s03-t08-evidence-05.log'),
}

for name, d in files.items():
    print(name, "parsed cases:", len(d))

min_max = min(max(int(c.split('-')[-1]) for c in d) for d in files.values())
print("min of per-file max case number:", min_max)

mismatches = 0
for i in range(1, min_max + 1):
    case_id = f"audit-route-s03-t08-{i:06d}"
    vals = {}
    for name, d in files.items():
        vals[name] = d.get(case_id)
    ref = vals['evidence-02.jsonl']
    for name, v in vals.items():
        if v != ref:
            mismatches += 1
            print("MISMATCH", case_id, name, v, "vs jsonl", ref)
print("Total mismatches over shared range 1..%d:" % min_max, mismatches)

expected = {1: ('macos-arm64', 'review'), 2: ('linux-x86_64', 'recorded'), 3: ('windows-x86_64', 'follow-up'), 0: ('freebsd-x86_64', 'supported')}
for name, d in files.items():
    violations = 0
    for case_id, (system, status, note) in d.items():
        n = int(case_id.split('-')[-1])
        exp_system, exp_status = expected[n % 4]
        if system != exp_system or status != exp_status:
            violations += 1
    print(name, "rotation violations over full own range (n=%d):" % len(d), violations)
