cd "/private/var/folders/sp/k4h4yd5j4bj0zwbwzps0yj8c0000gp/T/lcm-live-xxyb_t_3/audit-route-s03/maintenance/inputs/s03-checksum-ledger" && python3 << 'EOF'
import json, csv, re

def parse_md(path):
    out = {}
    with open(path) as f:
        for line in f:
            m = re.match(r'- \*\*(\S+)\*\* \| System: (\S+) \| Status: (\S+) \|', line)
            if m:
                out[m.group(1)] = (m.group(2), m.group(3))
    return out

def parse_jsonl(path):
    out = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            d = json.loads(line)
            out[d['case']] = (d['system'], d['status'])
    return out

def parse_csv(path):
    out = {}
    with open(path) as f:
        r = csv.DictReader(f)
        for row in r:
            out[row['case']] = (row['system'], row['status'])
    return out

def parse_yaml(path):
    out = {}
    case = system = status = None
    with open(path) as f:
        for line in f:
            line = line.rstrip('\n')
            if line.startswith('- case:'):
                case = line.split(':', 1)[1].strip()
            elif line.strip().startswith('system:'):
                system = line.split(':', 1)[1].strip()
            elif line.strip().startswith('status:'):
                status = line.split(':', 1)[1].strip()
                out[case] = (system, status)
    return out

def parse_log(path):
    out = {}
    with open(path) as f:
        for line in f:
            m = re.match(r'case=(\S+) system=(\S+) status=(\S+) note=', line)
            if m:
                out[m.group(1)] = (m.group(2), m.group(3))
    return out

files = {
    'md': parse_md('audit-route-s03-t10-evidence-01.md'),
    'jsonl': parse_jsonl('audit-route-s03-t10-evidence-02.jsonl'),
    'csv': parse_csv('audit-route-s03-t10-evidence-03.csv'),
    'yaml': parse_yaml('audit-route-s03-t10-evidence-04.yaml'),
    'log': parse_log('audit-route-s03-t10-evidence-05.log'),
}

for name, d in files.items():
    nums = sorted(int(k.split('-')[-1]) for k in d)
    print(name, 'count=', len(d), 'min=', nums[0], 'max=', nums[-1])

# shared range across all files
shared_max = min(max(int(k.split('-')[-1]) for k in d) for d in files.values())
print('shared_max =', shared_max)

mismatches = 0
for i in range(1, shared_max + 1):
    case = f"audit-route-s03-t10-{i:06d}"
    vals = set()
    for name, d in files.items():
        vals.add(d.get(case))
    if len(vals) != 1:
        mismatches += 1
        print('MISMATCH', case, {name: d.get(case) for name, d in files.items()})
print('mismatches over shared range 1..%d =' % shared_max, mismatches)

# rotation mapping check (mod4 -> system/status) using md as reference over its own full range
md = files['md']
mapping = {}
violations = 0
for k, (system, status) in md.items():
    n = int(k.split('-')[-1])
    mod = n % 4
    key = (system, status)
    if mod not in mapping:
        mapping[mod] = key
    elif mapping[mod] != key:
        violations += 1
print('rotation mapping (mod4 -> system,status):', mapping)
print('rotation violations in md:', violations)

# check same mapping holds in each file's own full range
for name, d in files.items():
    local_map = {}
    local_violations = 0
    for k, (system, status) in d.items():
        n = int(k.split('-')[-1])
        mod = n % 4
        key = (system, status)
        if mod not in local_map:
            local_map[mod] = key
        elif local_map[mod] != key:
            local_violations += 1
    print(name, 'local mapping:', local_map, 'violations:', local_violations)
EOF

